//! Writes `src/brand/mzizi-palette.generated.ts` from the `mzizi-tokens` crate.
//!
//!   cargo run -p verify-palette --bin generate             write the file
//!   cargo run -p verify-palette --bin generate -- --check  fail if it is not what the crate says
//!
//! The 21 families' dark and light hex are not authored on this site: they are the crate's constants.
//! `minerals.ts` and `palette.ts` import them from the generated file instead of carrying a copy,
//! so a re-sync is a version bump here and a regenerate, never an edit of a hex value.

use std::{env, fs, path::PathBuf, process::exit};
use verify_palette::CRATE;

fn render() -> String {
    let mut out = String::new();
    out.push_str("// GENERATED by `pnpm palette` (tools/verify-palette, bin `generate`) from mzizi-tokens =0.7.0.\n");
    out.push_str("// Do not edit: bump the crate pin, run `pnpm palette`, commit.\n\n");
    out.push_str("/** The 21 Mzizi families: dark-surface and light-surface hex, exactly as the crate publishes them. */\n");
    out.push_str("export const MZIZI_PALETTE = {\n");
    for (name, dark, light) in CRATE {
        out.push_str(&format!("  {name}: {{ dark: '{dark}', light: '{light}' }},\n"));
    }
    out.push_str("} as const;\n");
    out
}

fn main() {
    let path = PathBuf::from(concat!(env!("CARGO_MANIFEST_DIR"), "/../../src/brand/mzizi-palette.generated.ts"));
    let want = render();
    if env::args().any(|a| a == "--check") {
        if fs::read_to_string(&path).ok().as_deref() != Some(want.as_str()) {
            eprintln!("src/brand/mzizi-palette.generated.ts is stale: run `pnpm palette` and commit.");
            exit(1);
        }
        println!("mzizi-palette.generated.ts is up to date (mzizi-tokens =0.7.0)");
        return;
    }
    fs::write(&path, want).expect("write the generated palette");
    println!("wrote src/brand/mzizi-palette.generated.ts");
}
